mapper.update:
UPDATE travel_plan_members
SET status = #{toStatus},
    left_at = CURRENT_TIMESTAMP,
    rejoin_allowed = 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND travel_plan_id = #{travelPlanId}
  AND status = #{fromStatus}
  AND role = #{role}

UPDATE travel_plan_members
SET status = #{toStatus},
    removed_at = CURRENT_TIMESTAMP,
    rejoin_allowed = 0,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND travel_plan_id = #{travelPlanId}
  AND status = #{fromStatus}
  AND role = #{role}

UPDATE travel_plan_members
SET status = #{toStatus},
    left_at = NULL,
    removed_at = NULL,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND travel_plan_id = #{travelPlanId}
  AND user_id = #{userId}
  AND status = #{fromStatus}
  AND rejoin_allowed = 1

UPDATE travel_plan_members
SET rejoin_allowed = 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND travel_plan_id = #{travelPlanId}
  AND status = #{memberStatus}
  AND role = #{role}
  AND rejoin_allowed = 0

